/* Phenomenon Atlas: Method, board help and event bindings. */
'use strict';
function openMethod() { const m = state.meta;
  $('#methodContent').innerHTML = `<p class="method-tour"><button type="button" class="text-btn" data-act="tour">New here? Take the tour →</button></p><h3>01 / Scope</h3><p>The analysis starts with ${fmt(m.episodes_master)} podcast episodes with eligible transcripts and matched YouTube videos. The collection covers ${longDate(m.date_from)} to ${longDate(m.date_to)}. A language model reads each transcript and extracts problem statements with quotes from the source. It also rates the episode’s relevance to strategy and entrepreneurship research. Quotes are checked against the transcript. Episodes below the relevance threshold of ${m.relevance_min}, along with identified non-English transcripts, are excluded. The current Atlas contains ${fmt(m.episodes)} episodes and ${fmt(m.problems)} verified problem statements.</p><h3>02 / Topics</h3><p>A text embedding model, bge-m3, represents the questions accompanying the problem statements as numerical vectors. Statements with similar meanings are grouped into ${fmt(m.topics)} topics. A language model names each topic from its representative problems. Each statement belongs to one topic. The Map places topics with similar problems near one another. Distances help arrange the display and should not be read as precise measures of similarity.</p><h3>03 / Podcast attention</h3><p>Episodes counts distinct podcast episodes that raise at least one problem within a topic during the selected period. Audience points weights each eligible episode by its YouTube views relative to videos uploaded in the same week. Its weight equals twice its percentile rank, giving up to two points per episode and about one on average. Comparing videos within upload weeks reduces differences in their time to collect views. It does not make view counts a measure of a problem’s importance or prevalence. Episodes are dated by YouTube upload date. When the YouTube and podcast dates differ by more than 60 days, the podcast date is used and the episode is excluded from Audience points.</p><h3>04 / Research fields</h3><p>The 17 research fields were developed from article keywords in six management journals. A language model scores each problem statement on these fields using its quote and surrounding passage. A statement receives a field label when its score is at least 50. A topic belongs to a field when at least 10 of its statements receive that label, they make up at least 5% of the topic, and that share is at least twice the field’s share across all statements. A topic may belong to several fields. Topics that meet no field’s criteria are placed in Others.</p><h3>05 / Core questions and papers</h3><p>A language model condenses related statements into core questions. A second model checks each question against its supporting quotes. Near-duplicate questions are merged within each topic. Up to eight questions are retained per topic, each supported by quotes from at least two podcast programs. Statements that do not support a core question still contribute to their topic’s episode count.</p><p>The literature index contains ${fmt(PAPER_LIBRARY)} articles from seven journals. It includes Academy of Management Journal, Academy of Management Review, Administrative Science Quarterly, Strategic Management Journal, Organization Science, Journal of Management, and selected departments of Management Science. Coverage begins in 1996 for the six journals and in 2003 for the selected Management Science departments, with additions published in 2026. Papers are dated by journal issue year.</p><p>For each core question, retrieval identifies up to 20 candidate articles using titles and abstracts. A language model rates their relevance from 0 to 100. Articles rated at least 60 are linked. Core papers score at least ${CORE_REL} and generally address the same question or mechanism. Peripheral papers score from 60 to 84. A topic’s paper count includes each linked article once, even if it relates to several core questions.</p><h3>06 / Ask</h3><p>Search retrieves existing topics related to your input.</p><p>The AI assistant helps you assess a research question’s practical relevance and potential. For one question in English, it summarizes how practitioners discuss the issue in podcast quotes and how retrieved papers have studied it. The assessment links to its supporting evidence.</p><p>Under <b>Your AI connection</b>, choose OpenAI or Claude and connect with an API key or an installed CLI. Codex CLI and Claude Code can use an existing login under the same operating-system account, regardless of the terminal folder used to sign in. Your question and selected evidence are sent to the chosen service. Internet access is required. You can also use the <a href="https://atlas.phenomenon.page/" target="_blank" rel="noopener">public website</a> without a personal AI connection. Everyone there shares 1,000 questions per day.</p><p>The assistant follows a predefined retrieval and assessment workflow. The program computes the counts, and the model interprets the retrieved quotes and papers. Its assessment is preliminary. A low paper count does not establish that a question is novel or that relevant research is absent.</p>`;
  $('#methodContent [data-act=tour]').onclick = () => { $('#methodDialog').close(); window.atlasTour && atlasTour.start(); };
  $('#methodDialog').showModal();
}
const HELP = {
  map: m => ['How to read the Map board', `<h3>Counts</h3><p><b>Episodes</b> counts each podcast episode that raises a problem within the topic once per period. <b>Audience points</b> gives an episode up to two points according to its video’s views relative to other videos uploaded in the same week. The average is about one point. When you select a research field, topic counts include only episodes whose problems are assigned to that field.</p>
<h3>Map</h3><p>Each name represents a topic. Topics with similar problems tend to appear near one another. Colour shows relative podcast attention around the topics in the current view. Red indicates more attention and blue less. Colours are recalculated when the selection changes, so they should not be used to compare absolute activity across periods. Zoom in to see more names. Click a name to open its topic.</p>
<h3>Squares</h3><p>Each square represents a topic. Rows represent research fields, and a topic can appear in more than one row. Topics run from fewer episodes or Audience points on the left to more on the right. The eight colour levels show their relative ranks in the selection. The total below a field name counts each episode once within that field. Changes from the previous period appear only when both periods are complete. Others is listed last. Click a square to open its topic, or a field name to enlarge its row.</p>
<h3>List</h3><p>The List ranks topics by Episodes or Audience points in the selected period and research field. Click a topic to open its questions, quotes and papers.</p>
<h3>Trend</h3><p>The three series show episodes per research field, the 20 topics with the most episodes in the collection period, and papers per research field. Podcast charts cover January to September 2026 because October is incomplete. Paper charts cover issue years 2006 to 2025. An episode or paper counts once within a field and may appear in several fields.</p><p>Each card shows the latest value and its change from the first displayed period. Hover over a line or tap it to read another value. Cards within each series share a scale. Fields are ranked by their latest value, and the top 20 topics by their total episode count. Select a field to highlight its series or restrict the top 20 topics. Each series also has a table of its values.</p>`],
  gap: m => ['How to read the Gap board', `<h3>Podcast attention</h3><p>Choose Episodes or Audience points, a period, and an optional research field. These controls use the same definitions as the Map board.</p>
<h3>Linked papers</h3><p><b>All related papers</b> counts distinct articles rated at least 60 for one or more of the topic’s core questions. <b>Core papers only</b> uses a threshold of ${CORE_REL}. An article linked to several questions within a topic counts once. These counts describe links found within the indexed journals, rather than all research on a topic.</p>
<h3>List</h3><p>Rank topics by podcast attention, paper count, or Gap. Gap is the topic’s percentile rank in podcast attention minus its percentile rank in paper count. Percentiles are calculated across all topics in the selected scope, with tied values assigned their average rank. A topic at the 90th percentile for podcasts and the 20th percentile for papers has a gap of 70. Positive values indicate relatively more podcast attention. Negative values indicate relatively more linked papers. The list displays the first 50 topics in the chosen order.</p>
<h3>Quadrant</h3><p>The horizontal axis ranks podcast attention, and the vertical axis ranks linked paper counts. The axes cross at the midpoint of each ranking. The lower-right quadrant contains topics with relatively more podcast attention and fewer linked papers. The upper-left contains the reverse. Small dots show all topics in the selection. Larger circles highlight a sample in each quadrant. Click a circle or label to open the topic.</p><p>The comparison can help identify questions to investigate. It does not show that practice or research is ahead, or establish a gap in the wider literature.</p>`],
  ask: m => ['How to read the Ask board', `<h3>Search</h3><p>Enter a phrase, research question or short description. Search uses a text embedding model to compare your input with topic descriptions and core questions. A topic’s score averages its description similarity and the similarity of its closest core question. Up to 10 topics with scores of at least 0.55 are returned. If none reaches the threshold, the three closest are shown as weak matches.</p><p>Search retrieves existing topics and does not generate an assessment. Open a topic or core question to inspect its quotes and linked papers. <b>Read in context</b> shows the quote with up to 200 words before and after it, with links to the podcast and YouTube video.</p><h3>AI assistant</h3><p>The AI assistant helps you assess a research question’s practical relevance and potential. For one question in English, it summarizes how practitioners discuss the issue in podcast quotes and how retrieved papers have studied it. The assessment links to its supporting evidence.</p><p>Under <b>Your AI connection</b>, choose OpenAI or Claude and connect with an API key or an installed CLI. Codex CLI and Claude Code can use an existing login under the same operating-system account, regardless of the terminal folder used to sign in. Your question and selected evidence are sent to the chosen service. Internet access is required. You can also use the <a href="https://atlas.phenomenon.page/" target="_blank" rel="noopener">public website</a> without a personal AI connection. Everyone there shares 1,000 questions per day.</p><p>The assistant follows a predefined retrieval and assessment workflow. The program computes the counts, and the model interprets the retrieved quotes and papers. Its assessment is preliminary. A low paper count does not establish that a question is novel or that relevant research is absent.</p><h3>Reading the assessment</h3><p><b>In podcasts</b> reports how many episodes contain a problem closely related to your question, using a similarity threshold of 0.60. No matching episodes gives “Not discussed in podcasts”; fewer than 10 gives “Rarely discussed in podcasts.” For larger counts, the program finds the topic containing the most matching episodes. It uses that topic’s episode rank to distinguish discussion below the median, in the upper half, or in the top tenth.</p><p><b>In papers</b> is based on the 20 retrieved articles. The model rates relevance from 0 to 100. The displayed level depends on how many score at least 85: none, one, two, or three or more. Articles rated at least 60 are listed with an explanation of their relevance. A label such as “Not studied in papers” refers only to this retrieved set.</p><p>The model selects three to five relevant quotes when suitable evidence is available. The overall assessment brings the podcast and paper evidence together. Follow the citations and read the original sources before relying on an interpretation.</p>`]
};
function openHelp() { const h = (HELP[state.board] || HELP.map)(state.meta); $('#helpTitle').textContent = h[0]; $('#helpContent').innerHTML = h[1]; $('#helpDialog').showModal(); }

/* ---------- ask board: built by ask.js and auth.js (ASK v2, 2026-10-21); askStatus() is defined there ---------- */

/* ---------- events ---------- */
function bind() {
  bindDetailResize(); bindTopicPage();   // app3.js
  $$('.rail-btn').forEach(b => b.onclick = () => setBoard(b.dataset.board)); $('#logoBtn').onclick = () => setBoard('home');
  $('#themeSelect').onchange = e => { state.theme = e.target.value; updateScopeNote(); closeDetail(true); transitionMap(); renderList(); };
  $('#themeBtn').onclick = () => applyTheme(!isLight()); $('#helpBtn').onclick = openHelp; $('#closeHelp').onclick = () => $('#helpDialog').close();
  $$('.mode-switch button').forEach(b => b.onclick = () => { state.mode = b.dataset.mode; const list = periodsOfMode(); const cur = periodObj(); const match = list.find(p => cur && p.start.slice(0, 7) <= cur.start.slice(0, 7) && (list[list.indexOf(p) + 1] ? list[list.indexOf(p) + 1].start.slice(0, 7) > cur.start.slice(0, 7) : true)); choosePeriod((match || list[list.length - 1]).id); });
  $$('.heat-switch button').forEach(b => b.onclick = () => { state.heat = b.dataset.heat; renderTime(); transitionMap(); renderList(); renderRank(); if (state.selected) renderDetail(); });
  $('#periodSelect').onchange = e => choosePeriod(e.target.value); $('#prevPeriod').onclick = () => { const l = periodsOfMode(), i = l.findIndex(p => p.id === state.period); if (i > 0) choosePeriod(l[i - 1].id); }; $('#nextPeriod').onclick = () => { const l = periodsOfMode(), i = l.findIndex(p => p.id === state.period); if (i < l.length - 1) choosePeriod(l[i + 1].id); };
  const setView = v => { state.view = v; [['map', '#viewMap'], ['squares', '#viewSquares'], ['list', '#viewList'], ['trend', '#viewTrend']].forEach(([k, id]) => $(id).classList.toggle('selected', k === v));
    $('#mapCanvas').hidden = v !== 'map'; $('.map-bottom').hidden = v !== 'map'; $('#listPanel').hidden = v !== 'list'; $('#squaresPanel').hidden = v !== 'squares'; $('#trendPanel').hidden = v !== 'trend';
    $('#timeLens').hidden = v === 'trend'; $('.scope-search').hidden = v === 'trend';   // the charts span the year and show no search
    paintHowto(v === 'trend' ? 'trend' : 'map'); hideTip(); hideSqTip(); state.hover = null; if (v === 'list') renderList(); else if (v === 'trend') renderTrend(); else transitionMap(); };
  $('#viewMap').onclick = () => setView('map'); $('#viewSquares').onclick = () => setView('squares'); $('#viewList').onclick = () => setView('list'); $('#viewTrend').onclick = () => setView('trend');
  $('#search').oninput = e => { state.search = e.target.value; state.zoom = 1; state.tx = 0; state.ty = 0; renderMap(); renderList(); };
  $('#closeDetail').onclick = () => closeDetail(); $$('.detail-tabs button').forEach(b => b.onclick = () => { state.tab = b.dataset.tab; renderDetail(); });
  $('#methodBtn').onclick = openMethod; $('#closeMethod').onclick = () => $('#methodDialog').close();
  $('#rankAcad').onchange = e => { state.acad = e.target.value; renderRank(); }; $('#rankBy').onchange = e => { state.rankBy = e.target.value; renderRank(); };
  $('#rankTheme').onchange = e => { state.rankTheme = e.target.value; closeDetail(true); renderRank(); }; $$('.rank-tabs button').forEach(b => b.onclick = () => { state.rtab = b.dataset.rtab; renderRank(); });
  const mc = $('#mapCanvas');
  mc.addEventListener('wheel', e => { e.preventDefault(); const box = mc.getBoundingClientRect(); const mx = e.clientX - box.left - box.width / 2, my = e.clientY - box.top - box.height / 2; const f = e.deltaY < 0 ? 1.18 : 1 / 1.18; const z = Math.max(.7, Math.min(8, state.zoom * f)); const k = z / state.zoom; state.tx = mx - (mx - state.tx) * k; state.ty = my - (my - state.ty) * k; state.zoom = z; renderMap({quick: true}); settle(); $('#zoomReset').textContent = Math.round(z * 100) + '%'; }, {passive: false});
  const settle = () => { clearTimeout(state.settleT); state.settleT = setTimeout(() => renderMap(), 160); };
  mc.addEventListener('mousedown', e => { if (e.target.closest('.topic-label')) return; state.drag = {x: e.clientX, y: e.clientY, tx: state.tx, ty: state.ty, moved: false}; mc.classList.add('dragging'); });
  window.addEventListener('mousemove', e => {
    if (state.drag) { const dx = e.clientX - state.drag.x, dy = e.clientY - state.drag.y; if (Math.abs(dx) + Math.abs(dy) > 3) state.drag.moved = true; state.tx = state.drag.tx + dx; state.ty = state.drag.ty + dy; renderMap({quick: true}); settle(); } });
  window.addEventListener('mouseup', e => { if (!state.drag) return; const moved = state.drag.moved; state.drag = null; mc.classList.remove('dragging'); if (!moved && !e.target.closest('.topic-label') && e.target.closest('#mapCanvas')) { const t = nearestTopic(e); if (t) selectTopic(t.id); } });
  const zoomBy = f => { const z = Math.max(.7, Math.min(8, state.zoom * f)), k = z / state.zoom; animateCamera({zoom: z, tx: state.tx * k, ty: state.ty * k}, 320); };
  $('#zoomIn').onclick = () => zoomBy(1.3); $('#zoomOut').onclick = () => zoomBy(1 / 1.3); $('#zoomReset').onclick = () => flyHome();
  window.addEventListener('resize', () => { renderMap(); if (state.board === 'gap' && state.rtab === 'quad') renderRank(); });
}
load().then(openFromHash).catch(e => { $('#boardCopy').textContent = 'Failed to load data: ' + e; console.error(e); });
